create Proc [dbo].[GetDataForForm] @XML as xml as  BEGIN TRY    BEGIN TRANSACTION   begin  declare @count as int; set @count = 0; if @count = 0 begin  truncate table Table1 insert into Table1(id) SELECT  myXML.value('./@id','nvarchar(50)') FROM @XML.nodes('/doc/title') As nodes(myXML); select @count = count(id) from Table1 if @count > 0 begin UPDATE dine_in_order SET Od = 0,status = 1 FROM dine_in_order t1 INNER JOIN Table1 t2 ON t1.id = t2.id truncate table Table1 select @count = count(id) from Table1 if @count=0 begin UPDATE order_payment SET status = 1 FROM order_payment t1 INNER JOIN dine_in_order t2 ON t1.order_key = t2.id where t2.status = 1 UPDATE order_detail SET status = 1 FROM order_detail t1 INNER JOIN dine_in_order t2 ON t1.order_key = t2.id where t2.status = 1 UPDATE Discount SET status = 1 FROM Discount t1 INNER JOIN dine_in_order t2 ON t1.order_key = t2.id where t2.status = 1 UPDATE POSSaleReturnMaster SET status = 1 FROM POSSaleReturnMaster t1 INNER JOIN dine_in_order t2 ON t1.OrderKey = t2.id where t2.status = 1 UPDATE Item_less SET status = 1 FROM Item_less t1 INNER JOIN dine_in_order t2 ON t1.order_key = t2.id where t2.status = 1 UPDATE Item_delete SET status = 1 FROM Item_delete t1 INNER JOIN dine_in_order t2 ON t1.order_key = t2.id where t2.status = 1 insert into Table1(id) SELECT id  FROM dine_in_order where status = 0 order by id; select @count = count(id) from Table1 if @count > 0 begin UPDATE dine_in_order SET Od = t2.Od FROM dine_in_order t1 INNER JOIN Table1 t2 ON t1.id = t2.id truncate table Table1 end  end  end  end  end    COMMIT END TRY BEGIN CATCH   IF @@TRANCOUNT > 0     ROLLBACK   exec uspGetErrorInfo END CATCH Select * from Table1